INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('below the radar', '未引起注意；低調', 'not attracting attention or notice', '[{"en":"The competitor has been operating below the radar.","zh-TW":"這個競爭對手一直在低調運營。"},{"en":"We kept the new product below the radar until launch.","zh-TW":"我們在發布前讓新產品保持低調。"}]', 'prepositional phrase'),
('beyond one''s control', '超出控制範圍；無法控制的', 'outside the ability to influence or manage', '[{"en":"The delay is beyond our control due to weather.","zh-TW":"由於天氣原因，延誤超出了我們的控制範圍。"},{"en":"Some risks are beyond any team''s control.","zh-TW":"有些風險超出任何團隊的控制範圍。"}]', 'prepositional phrase'),
('by default', '預設情況下；在無其他選項時', 'because no other option was chosen; as a fallback', '[{"en":"We won the contract by default when the rival withdrew.","zh-TW":"競爭對手退出後，我們預設獲得了合約。"},{"en":"By default the system logs all transactions.","zh-TW":"預設情況下系統記錄所有交易。"}]', 'prepositional phrase'),
('contrary to expectations', '與預期相反；出乎意料地', 'opposite to what was expected or predicted', '[{"en":"Contrary to expectations sales rose in Q4.","zh-TW":"與預期相反，第四季銷售額上升了。"},{"en":"Contrary to expectations the product found a new market.","zh-TW":"出乎意料地，產品找到了新市場。"}]', 'prepositional phrase'),
('down to the wire', '到最後一刻；直到最後關頭', 'continuing until the very last moment', '[{"en":"Negotiations went down to the wire before an agreement was reached.","zh-TW":"談判持續到最後一刻才達成協議。"},{"en":"The project was completed down to the wire.","zh-TW":"專案一直到最後關頭才完成。"}]', 'prepositional phrase'),
('for good measure', '附帶地；順便再加上', 'in addition to what is needed, as an extra precaution or bonus', '[{"en":"He added a year of warranty for good measure.","zh-TW":"他附帶地增加了一年保固。"},{"en":"Send the summary and attach the original report for good measure.","zh-TW":"傳送摘要並附上原始報告以作補充。"}]', 'prepositional phrase'),
('for the record', '為了存檔；鄭重聲明', 'stated formally so it is noted or documented', '[{"en":"For the record I objected to this proposal from the start.","zh-TW":"鄭重聲明，我從一開始就反對這個提案。"},{"en":"Let me note for the record that the budget was approved.","zh-TW":"為了存檔，我要記錄預算已獲批准。"}]', 'prepositional phrase'),
('close out', '結清；結束；平倉', 'to finalize or conclude; to clear remaining inventory or positions', '[{"en":"We need to close out the project before year end.","zh-TW":"我們需要在年底前結束這個專案。"},{"en":"Close out the inventory at a discount to make space.","zh-TW":"以折扣清倉以騰出空間。"}]', 'phrasal verb'),
('come apart', '崩潰；分裂；瓦解', 'to fall apart or break down; to lose cohesion', '[{"en":"The plan came apart when the key vendor dropped out.","zh-TW":"當關鍵供應商退出後計劃崩潰了。"},{"en":"The team came apart under the pressure of tight deadlines.","zh-TW":"在緊迫截止日期的壓力下團隊開始瓦解。"}]', 'phrasal verb'),
('come around', '轉變立場；接受新想法', 'to change one''s opinion and agree with someone', '[{"en":"He eventually came around to supporting the new policy.","zh-TW":"他最終轉變立場，支持了新政策。"},{"en":"The board came around to the restructuring proposal.","zh-TW":"董事會最終接受了重組提案。"}]', 'phrasal verb'),
('cut across', '跨越；橫切；涉及多個領域', 'to affect or involve multiple categories or groups', '[{"en":"This policy cuts across all departments.","zh-TW":"這項政策涉及所有部門。"},{"en":"The initiative cuts across traditional industry boundaries.","zh-TW":"這項計劃跨越了傳統行業界限。"}]', 'phrasal verb'),
('dig into', '深入探討；仔細研究', 'to examine or explore something thoroughly', '[{"en":"Let''s dig into the Q3 numbers more carefully.","zh-TW":"讓我們更仔細地深入研究第三季的數字。"},{"en":"She dug into the customer complaints to find the root cause.","zh-TW":"她深入探討了客戶投訴以找到根本原因。"}]', 'phrasal verb'),
('double down', '加倍努力；加大投入', 'to increase commitment to a strategy or action', '[{"en":"We decided to double down on our core market.","zh-TW":"我們決定加倍投入核心市場。"},{"en":"Double down on what''s working before exploring new channels.","zh-TW":"在探索新渠道之前加倍專注於有效的方法。"}]', 'phrasal verb'),
('fire up', '激勵；激發熱情；啟動', 'to energize or motivate someone; to start a system', '[{"en":"The CEO''s speech fired up the sales team.","zh-TW":"執行長的演講激勵了銷售團隊。"},{"en":"Fire up the new CRM system before the client meeting.","zh-TW":"在客戶會議前啟動新的CRM系統。"}]', 'phrasal verb'),
('front-load', '前置（費用或工作量）；提前集中', 'to place a larger portion of work, cost, or effort at the beginning', '[{"en":"The project was front-loaded with heavy testing phases.","zh-TW":"這個專案在前期集中了大量測試階段。"},{"en":"Front-load training to avoid costly mistakes later.","zh-TW":"提前集中培訓以避免後期代價高昂的錯誤。"}]', 'phrasal verb'),
('gear up', '準備就緒；備戰；積極準備', 'to prepare or get ready for an activity or challenge', '[{"en":"We are gearing up for the busy holiday season.","zh-TW":"我們正在為繁忙的假日旺季準備就緒。"},{"en":"The factory geared up production ahead of peak demand.","zh-TW":"工廠在需求高峰前積極準備提升產量。"}]', 'phrasal verb'),
('get ahead', '取得進展；先行一步；超越', 'to make progress; to advance ahead of others', '[{"en":"To get ahead we must invest in talent development.","zh-TW":"要取得進展，我們必須投資人才發展。"},{"en":"Get ahead of the regulatory changes by acting now.","zh-TW":"現在採取行動，以便在監管變化前先行一步。"}]', 'phrasal verb'),
('deliver on the promise', '兌現承諾；落實諾言', 'to follow through on what was promised', '[{"en":"The product must deliver on the promise made in the ads.","zh-TW":"產品必須兌現廣告中所做的承諾。"},{"en":"Deliver on the promise or risk losing trust.","zh-TW":"兌現承諾否則會失去信任。"}]', 'expression'),
('dog-eat-dog', '弱肉強食；激烈競爭的', 'highly competitive with little concern for others'' welfare', '[{"en":"It''s a dog-eat-dog market out there.","zh-TW":"外面是個弱肉強食的市場。"},{"en":"In a dog-eat-dog industry differentiation is crucial.","zh-TW":"在激烈競爭的行業中差異化至關重要。"}]', 'expression'),
('don''t burn bridges', '不要毀掉人脈；不要斷了退路', 'avoid damaging relationships that may be useful in the future', '[{"en":"Don''t burn bridges when you leave a company.","zh-TW":"離開公司時不要毀掉人脈。"},{"en":"Even in tough negotiations don''t burn bridges.","zh-TW":"即使在艱難談判中也不要斷了退路。"}]', 'expression'),
('elephant in the room', '眾所周知卻被刻意迴避的問題', 'an obvious problem that no one wants to discuss', '[{"en":"Let''s address the elephant in the room — we missed our targets.","zh-TW":"讓我們面對眾所周知的問題——我們沒有達到目標。"},{"en":"The budget shortfall was the elephant in the room.","zh-TW":"預算短缺是眾人迴避的問題。"}]', 'expression'),
('give the green light', '批准；開綠燈', 'to give approval to proceed with something', '[{"en":"Management gave the green light to the expansion.","zh-TW":"管理層批准了擴張計劃。"},{"en":"The committee gave the green light for the new policy.","zh-TW":"委員會批准了新政策。"}]', 'expression'),
('in the driver''s seat', '掌控局面；主導地位', 'in a position of control or authority', '[{"en":"Our brand is in the driver''s seat in the premium segment.","zh-TW":"我們的品牌在高端市場佔據主導地位。"},{"en":"With more data we put customers in the driver''s seat.","zh-TW":"有了更多數據，我們讓客戶掌控局面。"}]', 'expression'),
('keep one''s eye on the ball', '專注目標；保持專注', 'to remain focused on the main objective', '[{"en":"Keep your eye on the ball and don''t get distracted by secondary issues.","zh-TW":"保持專注，不要被次要問題分心。"},{"en":"Good managers keep their eye on the ball even under pressure.","zh-TW":"優秀的經理即使在壓力下也能保持目標專注。"}]', 'expression'),
('lay one''s cards on the table', '攤牌；坦誠相告', 'to be open and honest about one''s intentions or information', '[{"en":"In the final negotiation we laid our cards on the table.","zh-TW":"在最後談判中我們攤牌了。"},{"en":"Lay your cards on the table to build trust.","zh-TW":"坦誠相告以建立信任。"}]', 'expression'),
('outside the box', '突破常規；有創意地', 'thinking in a creative or unconventional way', '[{"en":"We need to think outside the box to solve this issue.","zh-TW":"我們需要突破常規來解決這個問題。"},{"en":"Thinking outside the box led to a breakthrough product.","zh-TW":"突破常規思維帶來了突破性產品。"}]', 'expression'),
('put one''s best foot forward', '全力以赴；展現最佳狀態', 'to make the best possible impression or effort', '[{"en":"Put your best foot forward in the client pitch.","zh-TW":"在客戶推介中全力以赴展現最佳狀態。"},{"en":"We put our best foot forward during the investor meeting.","zh-TW":"我們在投資者會議中展現了最佳狀態。"}]', 'expression'),
('seal the deal', '完成交易；成交', 'to finalize an agreement or close a sale', '[{"en":"The free pilot project helped seal the deal.","zh-TW":"免費試點項目幫助促成了交易。"},{"en":"A personal visit from the CEO sealed the deal.","zh-TW":"執行長的親自拜訪完成了這筆交易。"}]', 'expression'),
('take it to the next level', '更上一層樓；提升到更高境界', 'to improve or advance something to a higher standard', '[{"en":"We plan to take our customer experience to the next level.","zh-TW":"我們計劃將客戶體驗更上一層樓。"},{"en":"The new investment will take the platform to the next level.","zh-TW":"新投資將使平台提升到更高境界。"}]', 'expression'),
('the devil is in the details', '細節決定成敗；魔鬼藏在細節裡', 'small, often overlooked details can cause serious problems', '[{"en":"The devil is in the details of the contract terms.","zh-TW":"合約條款的細節決定成敗。"},{"en":"Review every clause — the devil is in the details.","zh-TW":"審查每個條款——魔鬼藏在細節裡。"}]', 'expression'),
('think on one''s feet', '即興應對；臨機應變', 'to make quick decisions without time to prepare', '[{"en":"Good salespeople can think on their feet during tough questions.","zh-TW":"優秀的銷售人員在面對棘手問題時能夠臨機應變。"},{"en":"She thinks on her feet brilliantly under pressure.","zh-TW":"她在壓力下即興應對的能力非常出色。"}]', 'expression'),
('turn the tables', '扭轉局勢；反敗為勝', 'to reverse a situation in your favor', '[{"en":"The competitor turned the tables with a surprise price cut.","zh-TW":"競爭對手以突然降價扭轉了局勢。"},{"en":"Innovation allowed us to turn the tables on industry rivals.","zh-TW":"創新使我們能夠反敗為勝對抗行業競爭者。"}]', 'expression'),
('on par with', '與…相當；旗鼓相當', 'equal to or at the same level as', '[{"en":"Our service quality is on par with industry leaders.","zh-TW":"我們的服務品質與行業領先者相當。"},{"en":"Salaries must be on par with market rates.","zh-TW":"薪資必須與市場水準相當。"}]', 'prepositional phrase'),
('on the brink of', '瀕臨；即將到達', 'very close to a significant event, often negative', '[{"en":"The company was on the brink of bankruptcy when rescued.","zh-TW":"公司在被救助時瀕臨破產。"},{"en":"We are on the brink of a major technology breakthrough.","zh-TW":"我們即將達到一個重大技術突破。"}]', 'prepositional phrase'),
('out of proportion', '不成比例；誇大其詞', 'not matching the scale or importance of something', '[{"en":"The media coverage was out of proportion to the actual issue.","zh-TW":"媒體報導相對於實際問題不成比例。"},{"en":"Don''t let a small setback grow out of proportion.","zh-TW":"不要讓小挫折被誇大其詞。"}]', 'prepositional phrase'),
('without prejudice', '在不損害權益的情況下；保留法律權益', 'without affecting one''s legal rights; used in negotiations to protect positions', '[{"en":"The settlement was discussed without prejudice.","zh-TW":"和解在保留法律權益的情況下進行了討論。"},{"en":"Mark offers as without prejudice in sensitive negotiations.","zh-TW":"在敏感談判中將提議標注為保留法律權益。"}]', 'prepositional phrase'),
('work in tandem', '協同合作；齊頭並進', 'to work together closely or simultaneously', '[{"en":"Sales and marketing work in tandem to close deals.","zh-TW":"銷售和行銷協同合作以達成交易。"},{"en":"The two systems work in tandem to process orders.","zh-TW":"這兩個系統齊頭並進地處理訂單。"}]', 'prepositional phrase'),
('leverage existing assets', '善用現有資產；充分利用現有資源', 'to use current resources or capabilities to gain advantage', '[{"en":"We leveraged existing assets to enter new markets quickly.","zh-TW":"我們善用現有資產快速進入新市場。"},{"en":"Leverage existing assets before investing in new ones.","zh-TW":"在投資新資產之前充分利用現有資產。"}]', 'business idiom'),
('market intelligence', '市場情報；市場資訊', 'information gathered about competitors, customers, and the market environment', '[{"en":"We invest in market intelligence to stay competitive.","zh-TW":"我們投資於市場情報以保持競爭力。"},{"en":"Market intelligence guided our pricing strategy.","zh-TW":"市場情報指導了我們的定價策略。"}]', 'business idiom'),
('net out', '淨餘；扣除後剩餘', 'to calculate the final amount after deductions', '[{"en":"Net out the fees before reporting profits.","zh-TW":"在報告利潤前扣除費用後的淨餘。"},{"en":"The gain netted out to about two million after taxes.","zh-TW":"扣除稅款後收益淨餘約兩百萬。"}]', 'phrasal verb'),
('opt in', '選擇加入；積極參與', 'to choose to participate in something', '[{"en":"Customers must opt in to receive marketing emails.","zh-TW":"客戶必須選擇加入才能接收行銷電子郵件。"},{"en":"Employees can opt in to the flexible work scheme.","zh-TW":"員工可以選擇加入彈性工作計劃。"}]', 'phrasal verb'),
('opt out', '選擇退出；放棄參與', 'to choose not to participate in something', '[{"en":"Users can opt out of data sharing at any time.","zh-TW":"用戶可以隨時選擇退出數據共享。"},{"en":"Several countries opted out of the trade deal.","zh-TW":"幾個國家選擇退出了這項貿易協議。"}]', 'phrasal verb'),
('pipe up', '開口說話；提出意見', 'to speak up and offer an opinion or suggestion', '[{"en":"Don''t hesitate to pipe up if you have a better idea.","zh-TW":"如果你有更好的想法不要猶豫，開口說出來。"},{"en":"He piped up with a valid concern during the briefing.","zh-TW":"他在簡報中提出了一個合理的問題。"}]', 'phrasal verb'),
('pitch in', '幫忙；出力；分擔', 'to contribute effort or resources to help', '[{"en":"Everyone pitched in to meet the urgent deadline.","zh-TW":"大家都幫忙以達到緊急截止日期。"},{"en":"Pitch in and help the team when it''s busy.","zh-TW":"在繁忙時出力幫助團隊。"}]', 'phrasal verb'),
('play out', '發展；展開；結果如何', 'to happen or develop in a particular way', '[{"en":"Let''s wait and see how the strategy plays out.","zh-TW":"讓我們等著看這個策略如何發展。"},{"en":"The worst-case scenario did not play out.","zh-TW":"最壞的情況沒有發展出來。"}]', 'phrasal verb'),
('plug away', '努力不懈；堅持做', 'to continue working hard at something despite difficulty', '[{"en":"The team plugged away at the issue for weeks.","zh-TW":"團隊在這個問題上努力不懈了好幾週。"},{"en":"Keep plugging away and the results will come.","zh-TW":"堅持努力，結果終將到來。"}]', 'phrasal verb'),
('reach out', '聯繫；主動接觸', 'to contact someone, especially to offer help or start a conversation', '[{"en":"Reach out to the client within 24 hours of the meeting.","zh-TW":"在會議後24小時內與客戶聯繫。"},{"en":"We reached out to potential investors at the conference.","zh-TW":"我們在會議上主動接觸了潛在投資者。"}]', 'phrasal verb'),
('ramp down', '逐步減少；縮減', 'to gradually reduce production, activity, or effort', '[{"en":"We ramped down production ahead of the retooling period.","zh-TW":"我們在改裝期前逐步減少了產量。"},{"en":"Ramp down project activities during the holiday season.","zh-TW":"在假日期間縮減專案活動。"}]', 'phrasal verb'),
('revolve around', '圍繞；以…為中心', 'to have something as the main focus or concern', '[{"en":"Our strategy revolves around customer satisfaction.","zh-TW":"我們的策略以客戶滿意度為中心。"},{"en":"The discussion revolved around budget allocation.","zh-TW":"討論圍繞預算分配展開。"}]', 'phrasal verb'),
('scale back', '縮減規模；削減', 'to reduce the size or scope of something', '[{"en":"We scaled back the project scope due to budget cuts.","zh-TW":"由於預算削減，我們縮減了專案範圍。"},{"en":"Scaling back expansion plans shows fiscal discipline.","zh-TW":"縮減擴張計劃顯示了財務紀律。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('scope out', '考察；評估；摸清情況', 'to investigate or assess the details of a situation or location', '[{"en":"She scoped out the competition before entering the market.","zh-TW":"她在進入市場之前考察了競爭情況。"},{"en":"Scope out the new location before committing to a lease.","zh-TW":"在簽訂租約前評估新地點。"}]', 'phrasal verb'),
('smooth out', '平息；消除；使順暢', 'to remove problems or difficulties; to make a process easier', '[{"en":"Let''s smooth out the onboarding process before launch.","zh-TW":"讓我們在發布前使入職流程更順暢。"},{"en":"She smoothed out the tensions between the two teams.","zh-TW":"她平息了兩個團隊之間的緊張局勢。"}]', 'phrasal verb'),
('move fast and break things', '快速行動，勇於嘗試', 'to prioritize speed of innovation over caution', '[{"en":"The startup culture was move fast and break things.","zh-TW":"這家新創公司的文化是快速行動，勇於嘗試。"},{"en":"Move fast and break things works until compliance matters.","zh-TW":"快速行動勇於嘗試在合規不重要前是可行的。"}]', 'business idiom'),
('nail it and scale it', '先做好再擴大規模', 'to perfect a process or product before scaling widely', '[{"en":"The team focused on nail it and scale it for the first product.","zh-TW":"團隊專注於先把第一個產品做好再擴大規模。"},{"en":"Nail it and scale it prevents costly expansion mistakes.","zh-TW":"先做好再擴大規模可以防止代價高昂的擴張錯誤。"}]', 'business idiom'),
('needle mover', '帶來重大影響的事項；關鍵推動因素', 'an action or initiative that significantly impacts key metrics', '[{"en":"The partnership was a real needle mover for brand awareness.","zh-TW":"這次合作是品牌知名度的關鍵推動因素。"},{"en":"Focus resources on needle movers not vanity projects.","zh-TW":"將資源集中在帶來重大影響的事項上而不是形象工程。"}]', 'business idiom'),
('on the back burner', '暫時擱置；列為低優先', 'postponed or given low priority for now', '[{"en":"The expansion plan is on the back burner for now.","zh-TW":"擴張計劃目前暫時擱置。"},{"en":"Don''t put customer satisfaction on the back burner.","zh-TW":"不要將客戶滿意度列為低優先。"}]', 'business idiom'),
('one-stop shop', '一站式服務；全方位服務提供者', 'a provider that offers everything needed in one place', '[{"en":"We position ourselves as a one-stop shop for SME accounting.","zh-TW":"我們定位為中小企業會計的一站式服務提供者。"},{"en":"A one-stop shop approach increases client retention.","zh-TW":"一站式服務方法提高了客戶留存率。"}]', 'business idiom'),
('open the kimono', '公開資訊；透明化', 'to share confidential information or be fully transparent', '[{"en":"We opened the kimono to investors during due diligence.","zh-TW":"在盡職調查期間我們向投資者公開了資訊。"},{"en":"Opening the kimono can build trust with key partners.","zh-TW":"透明化可以與主要合作夥伴建立信任。"}]', 'business idiom'),
('over-index', '過度集中於；偏重某方面', 'to allocate disproportionately more attention or resources to something', '[{"en":"We tend to over-index on enterprise clients.","zh-TW":"我們傾向於過度集中於企業客戶。"},{"en":"Avoid over-indexing on short-term metrics.","zh-TW":"避免偏重短期指標。"}]', 'business idiom'),
('paralysis by analysis', '分析癱瘓；過度分析導致無法決策', 'being unable to make a decision because of excessive analysis', '[{"en":"Paralysis by analysis prevented us from launching on time.","zh-TW":"分析癱瘓使我們無法按時推出產品。"},{"en":"Set a deadline to avoid paralysis by analysis.","zh-TW":"設定截止日期以避免過度分析導致無法決策。"}]', 'business idiom'),
('peel back the layers', '層層剖析；深入了解', 'to analyze something progressively to understand its true nature', '[{"en":"We need to peel back the layers of this issue.","zh-TW":"我們需要層層剖析這個問題。"},{"en":"Peel back the layers before proposing a solution.","zh-TW":"在提出解決方案前深入了解情況。"}]', 'business idiom'),
('people-first culture', '以人為本的文化', 'an organizational philosophy that prioritizes employee well-being', '[{"en":"A people-first culture drives long-term retention.","zh-TW":"以人為本的文化推動長期員工留任。"},{"en":"The company is known for its people-first culture.","zh-TW":"這家公司以其以人為本的文化而聞名。"}]', 'business idiom'),
('pick your battles', '選擇性地應對；只爭最重要的', 'to choose carefully which issues to confront and which to let go', '[{"en":"In corporate politics you need to pick your battles.","zh-TW":"在企業政治中你需要選擇性地應對。"},{"en":"Pick your battles so you have energy for what truly matters.","zh-TW":"選擇你要爭的事，留精力給真正重要的事。"}]', 'business idiom'),
('pivot or persevere', '轉向還是堅持；策略抉擇', 'the decision whether to change strategy or continue as planned', '[{"en":"After the failed launch we faced a pivot or persevere decision.","zh-TW":"發布失敗後我們面臨轉向還是堅持的策略抉擇。"},{"en":"Pivot or persevere is a question every startup must answer.","zh-TW":"轉向還是堅持是每家新創公司必須回答的問題。"}]', 'business idiom'),
('plug a gap', '填補空缺；彌補不足', 'to fill a need or deficiency in a market, team, or process', '[{"en":"The new product plugs a significant gap in the market.","zh-TW":"新產品填補了市場上的重大空缺。"},{"en":"Hire a specialist to plug the skill gap.","zh-TW":"聘請專家來彌補技能不足。"}]', 'business idiom'),
('power player', '有影響力的人；重要玩家', 'a person or organization with significant influence or authority', '[{"en":"She became a power player in the fintech space within three years.","zh-TW":"她在三年內成為了金融科技領域的重要玩家。"},{"en":"Partnering with a power player accelerates growth.","zh-TW":"與有影響力的人合作加速了增長。"}]', 'business idiom'),
('proof of concept', '概念驗證', 'a demonstration that an idea or plan is feasible', '[{"en":"We ran a proof of concept before full development.","zh-TW":"在全面開發之前我們進行了概念驗證。"},{"en":"A proof of concept reduces investment risk.","zh-TW":"概念驗證降低了投資風險。"}]', 'business idiom'),
('pull the plug', '叫停；中止；終止', 'to stop a project, program, or initiative entirely', '[{"en":"The board pulled the plug on the unprofitable division.","zh-TW":"董事會叫停了不盈利的部門。"},{"en":"Know when to pull the plug before sinking more resources.","zh-TW":"在投入更多資源之前知道何時該中止。"}]', 'business idiom'),
('put a stake in the ground', '確立立場；明確目標', 'to make a definitive claim or decision about a position or goal', '[{"en":"We need to put a stake in the ground on pricing strategy.","zh-TW":"我們需要確立定價策略的立場。"},{"en":"Put a stake in the ground so the team has a clear goal.","zh-TW":"確立明確目標讓團隊有方向感。"}]', 'business idiom'),
('quick win', '快速見效的成果；短期勝利', 'a small, achievable goal that shows early progress', '[{"en":"Focus on quick wins to build team momentum early.","zh-TW":"專注於快速見效的成果以及早建立團隊動力。"},{"en":"Quick wins help secure stakeholder support.","zh-TW":"短期勝利有助於獲得利益相關者的支持。"}]', 'business idiom'),
('red ocean strategy', '紅海策略；激烈競爭市場', 'competing in an existing highly competitive market', '[{"en":"A red ocean strategy requires exceptional efficiency.","zh-TW":"紅海策略需要卓越的效率。"},{"en":"Consider a blue ocean approach rather than red ocean strategy.","zh-TW":"考慮藍海方法而不是紅海策略。"}]', 'business idiom'),
('revenue driver', '收入驅動因素', 'a product, channel, or activity that generates significant revenue', '[{"en":"The enterprise segment is our primary revenue driver.","zh-TW":"企業客戶群是我們主要的收入驅動因素。"},{"en":"Focus on the top revenue drivers for maximum impact.","zh-TW":"專注於最重要的收入驅動因素以獲得最大影響。"}]', 'business idiom'),
('right-size', '適當調整規模；優化規模', 'to adjust the size of a workforce or budget to fit current needs', '[{"en":"The company right-sized its workforce after the merger.","zh-TW":"合併後公司適當調整了員工規模。"},{"en":"Right-sizing the budget ensures sustainable operations.","zh-TW":"優化預算規模確保了可持續運營。"}]', 'business idiom'),
('roadblock', '障礙；阻礙', 'an obstacle preventing progress toward a goal', '[{"en":"Identify and remove roadblocks early in the project.","zh-TW":"在專案早期識別並移除障礙。"},{"en":"Bureaucracy is a major roadblock to innovation.","zh-TW":"官僚主義是創新的主要阻礙。"}]', 'business idiom'),
('scalable solution', '可擴展的解決方案', 'a solution that can grow efficiently as demand increases', '[{"en":"We designed a scalable solution that grows with customer needs.","zh-TW":"我們設計了一個隨客戶需求成長的可擴展解決方案。"},{"en":"A scalable solution reduces per-unit costs as volume grows.","zh-TW":"可擴展的解決方案在數量增長時降低單位成本。"}]', 'business idiom'),
('silo mentality', '孤島心態；各自為政', 'when departments or teams avoid sharing information with others', '[{"en":"Silo mentality hinders cross-functional collaboration.","zh-TW":"孤島心態阻礙了跨職能協作。"},{"en":"Break down silo mentality to improve efficiency.","zh-TW":"打破各自為政以提高效率。"}]', 'business idiom'),
('skin in the game', '切身利益；真正的投入', 'having a personal stake or investment in the outcome', '[{"en":"Founders should have skin in the game to stay motivated.","zh-TW":"創始人應有切身利益才能保持動力。"},{"en":"Partners with skin in the game work harder for results.","zh-TW":"有真正投入的合作夥伴更努力爭取成果。"}]', 'business idiom'),
('soft launch', '軟發布；低調推出', 'a limited or quiet product launch without full marketing support', '[{"en":"We did a soft launch to test the market reaction.","zh-TW":"我們進行了軟發布以測試市場反應。"},{"en":"A soft launch allows for quick iteration before full rollout.","zh-TW":"軟發布允許在全面推出前快速迭代。"}]', 'business idiom'),
('stakeholder alignment', '利益相關者一致性；達成各方共識', 'ensuring all involved parties have a shared understanding and goal', '[{"en":"Stakeholder alignment is critical before starting major initiatives.","zh-TW":"在開始重大計劃之前達成利益相關者一致性至關重要。"},{"en":"Lack of stakeholder alignment caused project delays.","zh-TW":"缺乏利益相關者一致性導致了專案延誤。"}]', 'business idiom'),
('stretch goal', '延伸性目標；挑戰性目標', 'an ambitious target that is beyond normal expectations', '[{"en":"Our stretch goal is to double revenue in one year.","zh-TW":"我們的挑戰性目標是在一年內使收入翻倍。"},{"en":"Stretch goals inspire innovation but must be realistic.","zh-TW":"挑戰性目標激發創新但必須現實。"}]', 'business idiom'),
('sweet spot', '最佳平衡點；黃金地帶', 'the ideal intersection of two factors for optimal results', '[{"en":"Find the sweet spot between cost and quality.","zh-TW":"找到成本與品質之間的最佳平衡點。"},{"en":"The new product sits in the sweet spot for the market.","zh-TW":"新產品處於市場的黃金地帶。"}]', 'business idiom'),
('synergy realization', '協同效益實現', 'achieving the expected benefits from combining organizations or teams', '[{"en":"Synergy realization was slower than expected post-merger.","zh-TW":"合併後協同效益實現比預期慢。"},{"en":"Set clear milestones for synergy realization.","zh-TW":"為協同效益實現設定明確里程碑。"}]', 'business idiom'),
('time to market', '上市時間；從開發到推出的時間', 'the time from product development to commercial availability', '[{"en":"Agile methods reduce time to market significantly.","zh-TW":"敏捷方法顯著縮短了上市時間。"},{"en":"Time to market is a key competitive advantage.","zh-TW":"上市時間是關鍵的競爭優勢。"}]', 'business idiom'),
('tipping point', '引爆點；臨界點', 'the moment when a trend or change becomes unstoppable', '[{"en":"Digital payments reached a tipping point during the pandemic.","zh-TW":"數位支付在疫情期間達到了引爆點。"},{"en":"We are at the tipping point of mainstream AI adoption.","zh-TW":"我們正處於人工智慧主流採用的臨界點。"}]', 'business idiom'),
('top of mind', '首要考量；念念不忘', 'being the first thing thought of when considering a category', '[{"en":"Keep your brand top of mind with regular touchpoints.","zh-TW":"通過定期接觸點讓你的品牌保持在首要考量中。"},{"en":"Customer retention should be top of mind for leadership.","zh-TW":"客戶留存率應該是領導層念念不忘的事。"}]', 'business idiom'),
('stumble upon', '偶然發現；碰巧遇到', 'to find or encounter something unexpectedly', '[{"en":"We stumbled upon a potential acquisition target at the conference.","zh-TW":"我們在會議上偶然發現了一個潛在的收購目標。"},{"en":"She stumbled upon a creative solution while reviewing old data.","zh-TW":"她在查看舊數據時碰巧遇到了一個創意解決方案。"}]', 'phrasal verb'),
('take away', '帶走；扣除；學到', 'to remove or learn something from a situation', '[{"en":"What do you take away from this project experience?","zh-TW":"你從這個專案經驗中學到了什麼？"},{"en":"Take away the high performer''s support and morale drops.","zh-TW":"如果帶走了高績效員工的支持，士氣就會下降。"}]', 'phrasal verb'),
('unlock value', '釋放價值；創造潛在價值', 'to reveal or realize potential value in an asset or situation', '[{"en":"The merger unlocked significant value for shareholders.","zh-TW":"合併為股東釋放了顯著的價值。"},{"en":"Our goal is to unlock value in underperforming assets.","zh-TW":"我們的目標是在表現不佳的資產中創造潛在價值。"}]', 'phrasal verb'),
('zoom in', '深入聚焦；放大關注細節', 'to focus closely on a specific detail or aspect', '[{"en":"Let''s zoom in on the Q3 performance numbers.","zh-TW":"讓我們深入聚焦第三季績效數字。"},{"en":"Zoom in on the biggest cost driver before analyzing others.","zh-TW":"在分析其他因素之前放大關注最大的成本驅動因素。"}]', 'phrasal verb'),
('zoom out', '拉遠視角；從大局看', 'to take a broader perspective; to consider the bigger picture', '[{"en":"Sometimes you need to zoom out and see the bigger picture.","zh-TW":"有時你需要拉遠視角從大局看。"},{"en":"Zoom out to understand how the market is shifting.","zh-TW":"從大局出發了解市場如何在轉變。"}]', 'phrasal verb'),
('bank on it', '對此有把握；確信會發生', 'to be absolutely certain that something will happen', '[{"en":"If we deliver quality you can bank on repeat business.","zh-TW":"如果我們提供品質你可以對回購業務有把握。"},{"en":"She said she''d close the deal — you can bank on it.","zh-TW":"她說她會完成交易——你可以確信這一點。"}]', 'phrasal verb'),
('carve out', '開拓；劃出；創造（一席之地）', 'to create or establish a distinct area or share of something', '[{"en":"We carved out a niche in premium pet care products.","zh-TW":"我們在高端寵物護理產品中開拓了一個利基市場。"},{"en":"Carve out dedicated time for innovation projects.","zh-TW":"劃出專門的時間用於創新專案。"}]', 'phrasal verb'),
('cobble together', '拼湊；臨時組合', 'to put something together quickly from available materials', '[{"en":"We cobbled together a proposal overnight for the client.","zh-TW":"我們通宵為客戶拼湊了一份提案。"},{"en":"The team cobbled together a workaround before the fix.","zh-TW":"團隊在修復方案出來之前拼湊了一個臨時解決方法。"}]', 'phrasal verb'),
('collaborate on', '在…上合作；共同研發', 'to work together with others on a shared project or goal', '[{"en":"The two firms collaborated on a joint product launch.","zh-TW":"兩家公司在聯合產品發布上合作。"},{"en":"Collaborate on the proposal to strengthen your bid.","zh-TW":"共同合作提案以加強你的投標。"}]', 'phrasal verb'),
('communicate across', '跨越…進行溝通；向…傳達', 'to convey information effectively across different levels or groups', '[{"en":"Leaders must communicate across all levels of the organization.","zh-TW":"領導者必須跨越組織各層級進行溝通。"},{"en":"The policy change was communicated across all departments.","zh-TW":"政策變更向所有部門傳達了。"}]', 'phrasal verb'),
('compete for', '競爭；爭奪', 'to try to win or obtain something against others', '[{"en":"Three firms are competing for the government contract.","zh-TW":"三家公司在競爭政府合約。"},{"en":"We compete for top talent with tech giants.","zh-TW":"我們與科技巨頭爭奪頂尖人才。"}]', 'phrasal verb'),
('concentrate on', '專注於；集中精力於', 'to direct effort and attention to a specific task or goal', '[{"en":"This quarter we concentrate on improving retention.","zh-TW":"這個季度我們專注於提高留存率。"},{"en":"Concentrate on the highest-value activities first.","zh-TW":"首先集中精力於最高價值的活動。"}]', 'phrasal verb'),
('confirm in writing', '書面確認', 'to officially verify an agreement or decision via written document', '[{"en":"Always confirm in writing after a verbal agreement.","zh-TW":"口頭協議後務必書面確認。"},{"en":"Please confirm in writing your acceptance of the terms.","zh-TW":"請書面確認你接受條款。"}]', 'phrasal verb'),
('consolidate around', '圍繞…整合；集中於', 'to combine and organize resources or activities around a central focus', '[{"en":"The industry is consolidating around three major players.","zh-TW":"行業正在圍繞三大主要參與者整合。"},{"en":"Consolidate around your strongest product lines first.","zh-TW":"首先集中於你最強的產品線。"}]', 'phrasal verb'),
('contract out', '外包；委外', 'to hire an outside company to perform services', '[{"en":"We contracted out logistics to a third-party provider.","zh-TW":"我們將物流外包給了第三方供應商。"},{"en":"Contracting out IT support reduced our overhead.","zh-TW":"將IT支援委外降低了我們的間接費用。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('converge on', '集中；聚焦；達成共識', 'to come together or agree on a common point or solution', '[{"en":"The team converged on a single pricing model after debate.","zh-TW":"經過辯論後團隊就單一定價模型達成了共識。"},{"en":"Multiple trends are converging on the same market opportunity.","zh-TW":"多個趨勢正在集中於同一市場機會。"}]', 'phrasal verb'),
('cost out', '估算成本；計算費用', 'to calculate the cost of a project or action in detail', '[{"en":"We need to cost out the expansion before the board meeting.","zh-TW":"在董事會會議之前我們需要估算擴張的成本。"},{"en":"Cost out each option so we can compare them fairly.","zh-TW":"估算每個選項的成本以便公平比較。"}]', 'phrasal verb'),
('course correct', '糾正方向；調整路線', 'to adjust strategy or actions based on feedback or results', '[{"en":"The team course corrected after the mid-year review.","zh-TW":"團隊在年中審查後糾正了方向。"},{"en":"Agile teams are designed to course correct quickly.","zh-TW":"敏捷團隊的設計就是為了快速調整路線。"}]', 'phrasal verb'),
('crowd out', '排擠；佔據…的空間', 'to push out or displace something by taking up space or priority', '[{"en":"Large platforms crowd out smaller competitors.","zh-TW":"大型平台排擠了小型競爭者。"},{"en":"Urgent tasks can crowd out strategic work.","zh-TW":"緊急任務可能會排擠戰略性工作。"}]', 'phrasal verb'),
('a race to the bottom', '惡性競爭；爭相降低標準', 'a competition to offer the lowest price or lowest standards', '[{"en":"Competing purely on price leads to a race to the bottom.","zh-TW":"純粹在價格上競爭導致惡性競爭。"},{"en":"We refuse to enter a race to the bottom with low-cost rivals.","zh-TW":"我們拒絕與低成本競爭對手展開惡性競爭。"}]', 'expression'),
('against the clock', '與時間賽跑；爭分奪秒', 'working urgently because there is very little time left', '[{"en":"The team was working against the clock to meet the launch date.","zh-TW":"團隊正在與時間賽跑以趕上發布日期。"},{"en":"Against the clock we still delivered a quality product.","zh-TW":"儘管爭分奪秒我們仍然交付了高品質的產品。"}]', 'prepositional phrase'),
('bang for your buck', '物超所值；高性價比', 'getting maximum value for the money spent', '[{"en":"Digital ads give us the best bang for our buck.","zh-TW":"數位廣告讓我們物超所值。"},{"en":"Choose suppliers who offer bang for your buck.","zh-TW":"選擇提供高性價比的供應商。"}]', 'expression'),
('between a rock and a hard place', '進退兩難；兩難困境', 'facing two equally difficult or unpleasant options', '[{"en":"We are between a rock and a hard place with this vendor.","zh-TW":"我們與這個供應商陷入了進退兩難的困境。"},{"en":"Between a rock and a hard place we chose the lesser risk.","zh-TW":"在進退兩難中我們選擇了風險較小的一方。"}]', 'expression'),
('blow the budget', '超出預算；大幅超支', 'to spend significantly more than the allocated budget', '[{"en":"The renovation blew the budget by 30%.","zh-TW":"翻修超出預算30%。"},{"en":"Avoid blowing the budget in the first half of the year.","zh-TW":"避免在上半年就大幅超支。"}]', 'expression'),
('break the ice', '打破僵局；活絡氣氛', 'to do or say something to relieve tension and start a conversation', '[{"en":"A quick team activity can break the ice at the start of a workshop.","zh-TW":"在工作坊開始時進行快速的團隊活動可以活絡氣氛。"},{"en":"She broke the ice with a relevant story.","zh-TW":"她用一個相關的故事打破了僵局。"}]', 'expression'),
('bring to the fore', '使突出；凸顯', 'to cause something to become prominent or important', '[{"en":"The crisis brought the team''s resilience to the fore.","zh-TW":"危機凸顯了團隊的韌性。"},{"en":"New data brought the efficiency gap to the fore.","zh-TW":"新數據使效率差距突出了。"}]', 'expression'),
('by a wide margin', '以相當大的差距；遙遙領先', 'by a large or significant amount', '[{"en":"Our product outperformed competitors by a wide margin.","zh-TW":"我們的產品以相當大的差距超越了競爭對手。"},{"en":"She won the client vote by a wide margin.","zh-TW":"她以遙遙領先的差距贏得了客戶投票。"}]', 'prepositional phrase'),
('by any measure', '無論以哪種標準衡量；毫無疑問', 'considered in any way; unquestionably', '[{"en":"By any measure the campaign was a success.","zh-TW":"無論以哪種標準衡量，這個活動都是成功的。"},{"en":"The cost savings are significant by any measure.","zh-TW":"無論怎麼看，成本節省都是顯著的。"}]', 'prepositional phrase'),
('by design', '有意為之；故意設計的', 'intentionally planned or intended', '[{"en":"The product is simple by design to reduce errors.","zh-TW":"產品有意為之地設計簡單以減少錯誤。"},{"en":"Our flat structure is by design to speed up decisions.","zh-TW":"我們的扁平化結構是故意設計的以加快決策。"}]', 'prepositional phrase'),
('case in point', '典型例子；恰當的例子', 'a clear example that illustrates the point being made', '[{"en":"The recent data breach is a case in point for stronger security.","zh-TW":"最近的數據洩露事件是加強安全性的典型例子。"},{"en":"Her rapid promotion is a case in point for performance-based culture.","zh-TW":"她的快速晉升是績效文化的恰當例子。"}]', 'expression'),
('common ground', '共同點；共識', 'shared beliefs or interests that can serve as a basis for agreement', '[{"en":"Find common ground before entering tough negotiations.","zh-TW":"在進入艱難談判前找到共同點。"},{"en":"There is common ground between the two proposals.","zh-TW":"兩個提案之間有共識。"}]', 'expression'),
('devil''s advocate', '故意反駁者；提出反對意見以測試論點', 'someone who argues a position they may not personally hold to test an argument', '[{"en":"Let me play devil''s advocate and challenge the assumptions.","zh-TW":"讓我扮演反對者的角色來挑戰這些假設。"},{"en":"We need someone to play devil''s advocate before the pitch.","zh-TW":"在推介前我們需要有人提出反對意見。"}]', 'expression'),
('fat chance', '幾乎不可能；機會渺茫', 'very unlikely to happen', '[{"en":"There''s a fat chance of closing that deal this quarter.","zh-TW":"這個季度完成那筆交易的機會渺茫。"},{"en":"Fat chance they''ll reduce prices in a seller''s market.","zh-TW":"在賣方市場他們幾乎不可能降低價格。"}]', 'expression'),
('firing on all cylinders', '全力以赴；全力運轉', 'operating at maximum capacity and efficiency', '[{"en":"The sales team is finally firing on all cylinders.","zh-TW":"銷售團隊終於全力以赴了。"},{"en":"When we''re firing on all cylinders results multiply.","zh-TW":"當我們全力運轉時結果就會倍增。"}]', 'expression'),
('for the long haul', '為了長遠；長久地', 'prepared for a long-term commitment or effort', '[{"en":"We are investing for the long haul in this market.","zh-TW":"我們在這個市場為了長遠進行投資。"},{"en":"Our partnerships are built for the long haul.","zh-TW":"我們的合作關係是為了長久而建立的。"}]', 'prepositional phrase'),
('from top to bottom', '從上到下；全面地', 'completely; involving all levels or aspects', '[{"en":"The organization was audited from top to bottom.","zh-TW":"組織從上到下進行了全面審計。"},{"en":"We redesigned the process from top to bottom.","zh-TW":"我們全面重新設計了這個流程。"}]', 'prepositional phrase'),
('give it your best shot', '盡力而為；全力嘗試', 'to make the greatest effort possible', '[{"en":"Give it your best shot even if success isn''t guaranteed.","zh-TW":"即使成功沒有保障也要盡力而為。"},{"en":"We gave it our best shot in the final bid round.","zh-TW":"在最後一輪投標中我們全力嘗試了。"}]', 'expression'),
('go back to the drawing board', '重頭開始；重新規劃', 'to abandon the current plan and start planning from the beginning', '[{"en":"After the failed test we went back to the drawing board.","zh-TW":"測試失敗後我們重頭開始了。"},{"en":"Go back to the drawing board if the client rejects the concept.","zh-TW":"如果客戶拒絕了概念就重新規劃。"}]', 'expression'),
('go-to person', '靈魂人物；首選對象', 'the person most relied upon for a particular skill or area', '[{"en":"She is the go-to person for regulatory compliance.","zh-TW":"她是監管合規方面的靠山人物。"},{"en":"Become the go-to person in your field to advance faster.","zh-TW":"成為你領域的首選對象以更快晉升。"}]', 'expression'),
('hang in the balance', '懸而未決；前途未卜', 'in a state of uncertainty where either outcome is possible', '[{"en":"The merger hung in the balance for three weeks.","zh-TW":"合併懸而未決長達三週。"},{"en":"With the vote tomorrow everything hangs in the balance.","zh-TW":"明天投票決定一切前途未卜。"}]', 'expression'),
('have the edge', '具有優勢；佔有上風', 'to have a slight advantage over competitors', '[{"en":"Our technology gives us the edge over rivals.","zh-TW":"我們的技術讓我們具有優勢超越對手。"},{"en":"Having the edge in talent is a sustainable advantage.","zh-TW":"在人才方面佔有上風是可持續的優勢。"}]', 'expression'),
('hold one''s ground', '堅守立場；不退讓', 'to refuse to change position under pressure', '[{"en":"She held her ground on the contract terms.","zh-TW":"她在合約條款上堅守了立場。"},{"en":"Holding your ground during a tough negotiation is essential.","zh-TW":"在艱難談判中不退讓至關重要。"}]', 'expression'),
('in a nutshell it', '簡而言之就是；一言以蔽之', 'to summarize a complex situation in very few words', '[{"en":"In a nutshell it comes down to cost and speed.","zh-TW":"簡而言之就是歸結為成本和速度。"},{"en":"Can you put the strategy in a nutshell for the board?","zh-TW":"你能為董事會一言以蔽之地概括策略嗎？"}]', 'expression'),
('in safe hands', '由可靠的人負責；安全託付', 'being looked after by a trustworthy and capable person', '[{"en":"The client account is in safe hands with our senior team.","zh-TW":"客戶帳戶由我們的資深團隊負責，十分可靠。"},{"en":"With her experience the project is in safe hands.","zh-TW":"憑藉她的經驗這個專案安全託付了。"}]', 'prepositional phrase'),
('in the driver''s seat on', '主導；掌控', 'in full control of the direction of something', '[{"en":"Sales is in the driver''s seat on this client relationship.","zh-TW":"銷售團隊主導著這個客戶關係。"},{"en":"We put the product team in the driver''s seat on strategy.","zh-TW":"我們讓產品團隊掌控策略方向。"}]', 'prepositional phrase'),
('in the final analysis', '歸根究柢；最終分析下來', 'when all factors are considered; ultimately', '[{"en":"In the final analysis growth depends on customer trust.","zh-TW":"歸根究柢增長取決於客戶信任。"},{"en":"In the final analysis results speak louder than promises.","zh-TW":"最終分析下來結果比承諾更有說服力。"}]', 'prepositional phrase'),
('know-how', '專業知識；技術訣竅', 'practical knowledge or expertise in doing something', '[{"en":"Our competitive edge is our deep industry know-how.","zh-TW":"我們的競爭優勢是我們深厚的行業知識。"},{"en":"Transfer know-how from senior staff to new hires.","zh-TW":"將技術訣竅從資深員工傳授給新員工。"}]', 'expression'),
('make headway', '取得進展；向前推進', 'to make steady progress towards a goal', '[{"en":"We are finally making headway on the partnership deal.","zh-TW":"我們終於在合夥交易上取得了進展。"},{"en":"Make headway early to build team confidence.","zh-TW":"儘早取得進展以建立團隊信心。"}]', 'expression'),
('nail it', '做得很好；完美執行', 'to do something perfectly or succeed brilliantly', '[{"en":"She really nailed it in the final pitch.","zh-TW":"她在最後的推介中真的做得非常好。"},{"en":"Nail it consistently and your reputation builds itself.","zh-TW":"持續完美執行你的聲譽自然建立。"}]', 'expression'),
('navigate through', '穿越；應對；在…中前行', 'to steer or work through a complex situation', '[{"en":"The team navigated through regulatory hurdles efficiently.","zh-TW":"團隊高效地應對了監管障礙。"},{"en":"Navigating through market volatility requires clear strategy.","zh-TW":"在市場波動中前行需要清晰的策略。"}]', 'phrasal verb'),
('negotiate down', '議價壓低；談判降低（價格）', 'to reduce a price or condition through negotiation', '[{"en":"We negotiated down the contract price by 15%.","zh-TW":"我們通過談判將合約價格壓低了15%。"},{"en":"Negotiate down the initial offer before signing.","zh-TW":"在簽署前談判壓低初始報價。"}]', 'phrasal verb'),
('number-crunch', '數字運算；詳細計算', 'to perform detailed financial or statistical calculations', '[{"en":"The finance team spent a week number-crunching the proposals.","zh-TW":"財務團隊花了一週時間詳細計算這些提案。"},{"en":"Number-crunch the data before the board presentation.","zh-TW":"在董事會演示前進行詳細的數字運算。"}]', 'phrasal verb'),
('onboard quickly', '快速入職；迅速上手', 'to train and integrate a new employee or client rapidly', '[{"en":"We redesigned the process to onboard clients more quickly.","zh-TW":"我們重新設計了流程以更快速地為客戶辦理入職。"},{"en":"Onboard quickly to reduce the ramp-up period.","zh-TW":"快速入職以縮短適應期。"}]', 'phrasal verb'),
('outsource to', '外包給；委外給', 'to contract work out to an external party', '[{"en":"We outsourced payroll processing to a specialist firm.","zh-TW":"我們將薪資處理外包給了專業公司。"},{"en":"Outsource to partners who have deeper expertise.","zh-TW":"外包給擁有更深專業知識的合作夥伴。"}]', 'phrasal verb'),
('overcommunicate', '過度溝通；頻繁傳達訊息', 'to communicate more frequently or thoroughly than might seem necessary', '[{"en":"During change management it''s better to overcommunicate.","zh-TW":"在變革管理過程中過度溝通總比不夠好。"},{"en":"Overcommunicate expectations so nothing is assumed.","zh-TW":"頻繁傳達期望以避免任何假設。"}]', 'phrasal verb'),
('overhaul completely', '全面改革；徹底改造', 'to completely redesign or reorganize something', '[{"en":"The HR process was completely overhauled last year.","zh-TW":"人力資源流程去年被全面改革了。"},{"en":"We overhauled the pricing model to improve margins.","zh-TW":"我們徹底改造了定價模型以提高利潤率。"}]', 'phrasal verb'),
('package up', '打包；包裝成產品形式', 'to bundle or present something as a complete offering', '[{"en":"Package up the services as a bundled solution for SMEs.","zh-TW":"將服務打包為中小企業的捆綁解決方案。"},{"en":"She packaged up the insights into an executive summary.","zh-TW":"她將洞察打包成了一份高管摘要。"}]', 'phrasal verb'),
('partner with', '與…合作；與…建立夥伴關係', 'to form a partnership with another organization or person', '[{"en":"We partnered with a local distributor to enter the market.","zh-TW":"我們與當地分銷商合作進入市場。"},{"en":"Partner with industry leaders to build credibility.","zh-TW":"與行業領先者建立夥伴關係以建立信譽。"}]', 'phrasal verb'),
('prioritize over', '優先於；把…放在…之前', 'to treat something as more important than something else', '[{"en":"Prioritize customer satisfaction over short-term profit.","zh-TW":"將客戶滿意度置於短期利潤之上。"},{"en":"We prioritized speed over perfection for the MVP.","zh-TW":"對最小可行性產品我們優先考慮速度而非完美。"}]', 'phrasal verb'),
('probe into', '深入調查；探究', 'to investigate or examine something closely', '[{"en":"The audit team probed into the financial discrepancies.","zh-TW":"審計團隊深入調查了財務差異。"},{"en":"Probe into customer complaints to find systemic issues.","zh-TW":"深入調查客戶投訴以找到系統性問題。"}]', 'phrasal verb'),
('prototype quickly', '快速製作原型；快速驗證', 'to rapidly build a basic version to test an idea', '[{"en":"Prototype quickly to test the concept with real users.","zh-TW":"快速製作原型以與真實用戶測試概念。"},{"en":"We prototype quickly and iterate based on feedback.","zh-TW":"我們快速製作原型並根據反饋進行迭代。"}]', 'phrasal verb'),
('pull together', '齊心協力；聯合起來', 'to work as a team toward a common goal', '[{"en":"The whole company pulled together to meet the deadline.","zh-TW":"全公司齊心協力趕上了截止日期。"},{"en":"We need to pull together and support each other.","zh-TW":"我們需要聯合起來相互支持。"}]', 'phrasal verb'),
('push back on', '反駁；抵制；推遲', 'to resist or object to something; to delay', '[{"en":"She pushed back on the unrealistic timeline.","zh-TW":"她反駁了不現實的時間表。"},{"en":"Push back on requests that fall outside scope.","zh-TW":"對超出範圍的請求予以抵制。"}]', 'phrasal verb'),
('quantify the impact', '量化影響；衡量成效', 'to measure the effect of something in numerical terms', '[{"en":"We tried to quantify the impact of the price change.","zh-TW":"我們試圖量化價格變化的影響。"},{"en":"Quantify the impact before presenting to leadership.","zh-TW":"在向領導層彙報前量化影響。"}]', 'phrasal verb'),
('rally around', '齊聚支持；共同支援', 'to come together to support a cause or person', '[{"en":"The team rallied around the new vision quickly.","zh-TW":"團隊很快齊聚支持新願景。"},{"en":"Employees rallied around the CEO during the crisis.","zh-TW":"危機期間員工齊聚支援執行長。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('resonate with', '引起共鳴；打動', 'to appeal to or make a strong impression on someone', '[{"en":"The brand''s message resonated with millennials.","zh-TW":"品牌信息引起了千禧一代的共鳴。"},{"en":"Create content that resonates with your target audience.","zh-TW":"創建能打動目標受眾的內容。"}]', 'phrasal verb'),
('revisit later', '稍後再討論；日後重新審視', 'to return to something at a future point', '[{"en":"Let''s table that and revisit it in the next meeting.","zh-TW":"讓我們先擱置那個問題，下次會議再討論。"},{"en":"Revisit the pricing model after the market test.","zh-TW":"市場測試後再重新審視定價模型。"}]', 'phrasal verb'),
('shift focus', '轉移焦點；改變重點', 'to change the emphasis or direction of attention', '[{"en":"We shifted focus from acquisition to retention.","zh-TW":"我們將焦點從獲客轉移到了留存。"},{"en":"Shift focus to enterprise clients for higher margins.","zh-TW":"將重點轉移到企業客戶以獲得更高利潤率。"}]', 'phrasal verb'),
('shore up', '強化；鞏固；支撐', 'to strengthen or reinforce something that is weak or threatened', '[{"en":"The new investment shores up our balance sheet.","zh-TW":"新投資強化了我們的資產負債表。"},{"en":"We need to shore up client confidence after the incident.","zh-TW":"事件後我們需要鞏固客戶信心。"}]', 'phrasal verb'),
('showcase to', '向…展示；展現給', 'to present something impressively to an audience', '[{"en":"The event showcases our innovation to global buyers.","zh-TW":"這個活動向全球買家展示了我們的創新。"},{"en":"Showcase the prototype to gather investor interest.","zh-TW":"向投資者展示原型以引起興趣。"}]', 'phrasal verb'),
('sign up for', '報名；訂閱；簽約加入', 'to formally register or commit to something', '[{"en":"Over 5000 businesses signed up for the beta.","zh-TW":"超過5000家企業報名參加了測試版。"},{"en":"Sign up for the training before spots fill up.","zh-TW":"在名額填滿之前報名參加培訓。"}]', 'phrasal verb'),
('slice and dice', '多角度分析；細分數據', 'to analyze data from multiple perspectives or categories', '[{"en":"We slice and dice the sales data by region and segment.","zh-TW":"我們按地區和細分市場對銷售數據進行多角度分析。"},{"en":"Slice and dice the results to identify hidden trends.","zh-TW":"細分結果以識別隱藏趨勢。"}]', 'phrasal verb'),
('stay on track', '保持進度；按計劃進行', 'to continue following the planned schedule or approach', '[{"en":"Weekly reviews help the team stay on track.","zh-TW":"每週審查幫助團隊保持進度。"},{"en":"Stay on track despite distractions or scope creep.","zh-TW":"儘管有干擾或範圍蔓延也要按計劃進行。"}]', 'phrasal verb'),
('streamline processes', '簡化流程；優化程序', 'to make processes more efficient by removing unnecessary steps', '[{"en":"We streamlined the approval process from five steps to two.","zh-TW":"我們將審批流程從五個步驟簡化到了兩個步驟。"},{"en":"Streamline processes to free up staff for higher-value tasks.","zh-TW":"簡化流程以釋放員工去做更高價值的任務。"}]', 'phrasal verb'),
('stress-test', '壓力測試；嚴格考驗', 'to evaluate how something performs under extreme or challenging conditions', '[{"en":"We stress-tested the financial model under adverse scenarios.","zh-TW":"我們在不利情景下對財務模型進行了壓力測試。"},{"en":"Stress-test your assumptions before the board presentation.","zh-TW":"在董事會演示前嚴格考驗你的假設。"}]', 'phrasal verb'),
('stretch budgets', '盡量延伸預算；最大化預算利用', 'to use resources more efficiently to do more with limited funds', '[{"en":"We had to stretch budgets to cover all initiatives.","zh-TW":"我們不得不盡量延伸預算以涵蓋所有計劃。"},{"en":"Stretch your marketing budget with organic content.","zh-TW":"通過有機內容最大化你的行銷預算利用。"}]', 'phrasal verb'),
('never mind the details', '不必在意細節；跳過細節', 'used to dismiss minor points and focus on the main issue', '[{"en":"Never mind the details — is the deal viable?","zh-TW":"不必在意細節——這筆交易可行嗎？"},{"en":"Never mind the minor errors and focus on the big picture.","zh-TW":"不要在意小錯誤，專注於大局。"}]', 'expression'),
('no questions asked', '不追問原因；無條件地', 'without requiring an explanation or justification', '[{"en":"We offer a 30-day refund no questions asked.","zh-TW":"我們提供30天退款，不追問原因。"},{"en":"The policy covers all returns no questions asked.","zh-TW":"政策涵蓋所有退貨，無條件受理。"}]', 'expression'),
('nothing ventured nothing gained', '不入虎穴焉得虎子；不冒險不成功', 'you cannot achieve success without taking risks', '[{"en":"We entered the new market — nothing ventured nothing gained.","zh-TW":"我們進入了新市場——不入虎穴焉得虎子。"},{"en":"Nothing ventured nothing gained is the entrepreneur''s motto.","zh-TW":"不冒險不成功是創業者的座右銘。"}]', 'expression'),
('odds are', '很可能；機率上來說', 'it is likely that something will happen', '[{"en":"Odds are the deal will close this month.","zh-TW":"很可能這筆交易本月就會完成。"},{"en":"The odds are in our favor given the market trends.","zh-TW":"從市場趨勢看機率對我們有利。"}]', 'expression'),
('on equal footing', '平等地；在同等基礎上', 'having the same standing or advantage as others', '[{"en":"The new rules put small firms on equal footing with large ones.","zh-TW":"新規則讓小公司與大公司在平等基礎上競爭。"},{"en":"We want all candidates assessed on equal footing.","zh-TW":"我們希望所有候選人都在平等基礎上接受評估。"}]', 'prepositional phrase'),
('on short notice', '短時間內；臨時通知地', 'with very little advance warning or preparation time', '[{"en":"We managed to organize the event on short notice.","zh-TW":"我們在短時間內設法籌辦了這次活動。"},{"en":"Thank you for responding on such short notice.","zh-TW":"感謝你在如此短的時間內做出回應。"}]', 'prepositional phrase'),
('on solid ground', '基礎穩固；立場站得住腳', 'in a secure or well-supported position', '[{"en":"Our legal position is on solid ground.","zh-TW":"我們的法律立場基礎穩固。"},{"en":"Ensure you are on solid ground before making the announcement.","zh-TW":"在發表聲明之前確保你的立場站得住腳。"}]', 'prepositional phrase'),
('on the front line', '在第一線；直接面對挑戰', 'in the most active or challenging position of an operation', '[{"en":"Customer service teams are on the front line of brand experience.","zh-TW":"客戶服務團隊在品牌體驗的第一線。"},{"en":"People on the front line understand real challenges best.","zh-TW":"在第一線的人最了解真實的挑戰。"}]', 'prepositional phrase'),
('on the go', '忙個不停；在行動中', 'very busy; in the middle of activities', '[{"en":"She''s always on the go with back-to-back client meetings.","zh-TW":"她總是忙個不停，客戶會議一個接一個。"},{"en":"Mobile tools help teams work on the go.","zh-TW":"行動工具幫助團隊在移動中工作。"}]', 'prepositional phrase'),
('on the right track', '方向正確；走在正軌上', 'proceeding correctly toward a desired goal', '[{"en":"The early results show we are on the right track.","zh-TW":"早期結果顯示我們走在正軌上。"},{"en":"We''re on the right track but need to accelerate.","zh-TW":"我們方向正確但需要加速。"}]', 'prepositional phrase'),
('on the spot', '當場；立即；在現場', 'immediately; without delay; in the exact location', '[{"en":"He made the decision on the spot without consulting others.","zh-TW":"他當場做出了決定，沒有諮詢其他人。"},{"en":"Be prepared to answer tough questions on the spot.","zh-TW":"準備好當場回答棘手問題。"}]', 'prepositional phrase'),
('on the upswing', '上升中；好轉中', 'in a period of improvement or growth', '[{"en":"Our market share is on the upswing after the relaunch.","zh-TW":"重新推出後我們的市場份額正在上升中。"},{"en":"The economy is on the upswing heading into Q4.","zh-TW":"進入第四季前經濟正在好轉中。"}]', 'prepositional phrase'),
('open to negotiation', '可以談判；有商量餘地', 'willing to discuss and adjust terms through negotiation', '[{"en":"The price is open to negotiation for volume orders.","zh-TW":"批量訂單的價格可以談判。"},{"en":"We''re open to negotiation on delivery terms.","zh-TW":"我們在交貨條款上有商量餘地。"}]', 'expression'),
('over the long term', '從長遠來看；長期內', 'considering a long period of time', '[{"en":"Over the long term brand equity outweighs short-term gains.","zh-TW":"從長遠來看品牌資產超過短期收益。"},{"en":"Our sustainability goals are designed over the long term.","zh-TW":"我們的可持續發展目標是著眼於長期規劃的。"}]', 'prepositional phrase'),
('pay dirt', '找到有利可圖的東西；獲得成功', 'to find or achieve something very valuable or successful', '[{"en":"The team hit pay dirt with the new product feature.","zh-TW":"團隊在新產品功能上找到了有利可圖的東西。"},{"en":"We finally hit pay dirt after months of market research.","zh-TW":"幾個月的市場研究後我們終於獲得了成功。"}]', 'expression'),
('piece of the pie', '分一杯羹；獲得一份份額', 'a share of something valuable, especially profits or market', '[{"en":"Everyone wants a piece of the pie in the booming sector.","zh-TW":"每個人都想在蓬勃發展的行業中分一杯羹。"},{"en":"We claim our piece of the pie with premium offerings.","zh-TW":"我們通過高端產品獲得市場份額。"}]', 'expression'),
('plain sailing', '一帆風順；順利無阻', 'an easy and trouble-free process', '[{"en":"After approval it should be plain sailing.","zh-TW":"獲批後應該一帆風順了。"},{"en":"The integration was plain sailing thanks to good planning.","zh-TW":"由於良好的規劃，整合過程一帆風順。"}]', 'expression'),
('play safe', '求穩；謹慎行事', 'to avoid risks by choosing safer options', '[{"en":"In uncertain markets it''s wise to play safe.","zh-TW":"在不確定的市場中謹慎行事是明智的。"},{"en":"Play safe with cash reserves when forecasting is unclear.","zh-TW":"在預測不清楚時對現金儲備求穩。"}]', 'expression'),
('play to strengths', '發揮優勢；揚長避短', 'to focus on areas where one has the greatest advantage', '[{"en":"Play to your team''s strengths when assigning roles.","zh-TW":"分配職責時要發揮團隊的優勢。"},{"en":"Our strategy is to play to our brand strengths.","zh-TW":"我們的策略是發揮我們的品牌優勢。"}]', 'expression'),
('position for growth', '為成長做好佈局；為增長做定位', 'to organize or develop in preparation for future expansion', '[{"en":"We are positioning the company for growth in Southeast Asia.","zh-TW":"我們正在為公司在東南亞的成長做佈局。"},{"en":"Position your team for growth by investing in training.","zh-TW":"通過投資培訓為團隊的成長做定位。"}]', 'expression'),
('practice what you preach', '言行一致；以身作則', 'to behave in a way consistent with your own advice or values', '[{"en":"Good leaders practice what they preach on transparency.","zh-TW":"優秀的領導者在透明度上言行一致。"},{"en":"Practice what you preach on work-life balance.","zh-TW":"在工作與生活平衡上以身作則。"}]', 'expression'),
('press the flesh', '握手寒暄；社交應酬', 'to shake hands and meet people at a social or business event', '[{"en":"The CEO pressed the flesh at the industry gala.","zh-TW":"執行長在行業晚宴上廣泛握手寒暄。"},{"en":"Pressing the flesh at trade shows builds lasting contacts.","zh-TW":"在貿易展覽上社交應酬建立了持久的聯繫。"}]', 'expression'),
('prior commitment', '預先承諾；既有的安排', 'an obligation that was already agreed to before a new request', '[{"en":"I can''t attend due to a prior commitment.","zh-TW":"我因為預先承諾無法出席。"},{"en":"Check for prior commitments before scheduling new meetings.","zh-TW":"在安排新會議前檢查既有的安排。"}]', 'prepositional phrase'),
('prove one''s worth', '證明自身價值；展示能力', 'to demonstrate that you are capable or valuable', '[{"en":"She proved her worth within the first three months.","zh-TW":"她在前三個月就證明了自身價值。"},{"en":"New hires must prove their worth before earning autonomy.","zh-TW":"新員工必須展示能力後才能獲得自主權。"}]', 'expression'),
('pull in the same direction', '朝同一方向努力；齊心協力', 'to work toward the same goal in a unified manner', '[{"en":"For success we all need to pull in the same direction.","zh-TW":"為了成功我們都需要朝同一方向努力。"},{"en":"Leadership must pull in the same direction or confuse the team.","zh-TW":"領導層必須齊心協力否則會讓團隊困惑。"}]', 'expression'),
('punch above one''s weight', '超水準發揮；表現優於預期', 'to perform at a higher level than your size or resources would suggest', '[{"en":"Our small team punches above its weight on innovation.","zh-TW":"我們的小型團隊在創新上超水準發揮。"},{"en":"The startup punches above its weight by partnering strategically.","zh-TW":"這家新創公司通過策略性合作表現優於預期。"}]', 'expression'),
('put the cart before the horse', '本末倒置；次序顛倒', 'to do things in the wrong order', '[{"en":"Launching before validating is putting the cart before the horse.","zh-TW":"在驗證之前就發布是本末倒置。"},{"en":"Don''t put the cart before the horse — test before scaling.","zh-TW":"不要次序顛倒——先測試再擴大規模。"}]', 'expression'),
('return to the fold', '回歸組織；重新加入', 'to come back to a group after a period of absence', '[{"en":"The veteran employee returned to the fold after two years away.","zh-TW":"這位資深員工離開兩年後回歸了組織。"},{"en":"Win back churned customers and help them return to the fold.","zh-TW":"贏回流失的客戶並幫助他們重新加入。"}]', 'expression'),
('rocket science', '困難的事；複雜難懂的事', 'something that is very difficult to understand or do (often used negatively)', '[{"en":"Improving customer response time isn''t rocket science.","zh-TW":"提高客戶響應時間並不是什麼複雜難懂的事。"},{"en":"It''s not rocket science — listen to the customer.","zh-TW":"這並不難——傾聽客戶就好了。"}]', 'expression'),
('second nature', '第二天性；自然而然', 'a skill or behavior that has become automatic through practice', '[{"en":"After training upselling became second nature for the team.","zh-TW":"培訓後向上銷售對團隊來說變得自然而然。"},{"en":"Managing objections becomes second nature with experience.","zh-TW":"處理異議隨著經驗積累變得自然而然。"}]', 'expression'),
('sell short', '低估；不重視自己（或他人）的能力', 'to undervalue someone or something; to sell stocks expecting price to fall', '[{"en":"Don''t sell yourself short in salary negotiations.","zh-TW":"在薪資談判中不要低估自己的能力。"},{"en":"The brand sold itself short by focusing only on price.","zh-TW":"這個品牌只專注於價格而不重視自身的價值。"}]', 'phrasal verb'),
('serve as', '作為；充當；擔任', 'to function as or act in a particular role', '[{"en":"This project serves as a model for future launches.","zh-TW":"這個專案作為未來發布的參考範本。"},{"en":"The pilot serves as proof of concept for investors.","zh-TW":"試點作為投資者的概念驗證。"}]', 'phrasal verb'),
('shed light on', '揭示；闡明；解釋', 'to clarify or provide insight into something', '[{"en":"The audit shed light on inefficiencies in the supply chain.","zh-TW":"審計揭示了供應鏈中的低效問題。"},{"en":"The research shed light on customer behavior patterns.","zh-TW":"研究闡明了客戶行為模式。"}]', 'phrasal verb'),
('shift gears', '改變方向；轉換策略', 'to change approach, topic, or direction', '[{"en":"Let''s shift gears and talk about the budget.","zh-TW":"讓我們改變方向談談預算問題。"},{"en":"The company shifted gears from hardware to software.","zh-TW":"公司從硬體轉換到了軟體策略。"}]', 'phrasal verb'),
('shoot for', '力求達到；設定目標', 'to aim for a particular goal or achievement', '[{"en":"We''re shooting for 20% growth this year.","zh-TW":"我們力求今年達到20%的增長。"},{"en":"Shoot for the stars but plan for realistic outcomes.","zh-TW":"力求最高目標但規劃現實的結果。"}]', 'phrasal verb'),
('shortlist candidates', '列入候選名單；入圍', 'to create a list of the most suitable candidates for selection', '[{"en":"We shortlisted three vendors for the final review.","zh-TW":"我們將三個供應商列入了最終審查的候選名單。"},{"en":"Shortlist based on both price and capability.","zh-TW":"根據價格和能力進行入圍篩選。"}]', 'phrasal verb'),
('show results', '展現成果；顯示效果', 'to demonstrate tangible outcomes from effort or investment', '[{"en":"The new campaign is already showing results.","zh-TW":"新的行銷活動已經在展現成果了。"},{"en":"We need to show results before the next funding round.","zh-TW":"在下一輪融資前我們需要展現成果。"}]', 'phrasal verb'),
('slim down', '精簡；縮減規模', 'to reduce the size or number of something, especially a team or process', '[{"en":"We slimmed down operations to improve profitability.","zh-TW":"我們精簡了運營以提高盈利能力。"},{"en":"Slim down the management layers for faster decisions.","zh-TW":"精簡管理層次以加快決策速度。"}]', 'phrasal verb'),
('speak to', '涉及；說明；回應', 'to address or relate to a specific topic or concern', '[{"en":"The proposal speaks to the client''s core needs.","zh-TW":"這份提案涉及了客戶的核心需求。"},{"en":"The data speaks to the effectiveness of the program.","zh-TW":"數據說明了這個計劃的有效性。"}]', 'phrasal verb');